<?php $notifications=ess_inbox($pdo,$user);$unread=count(array_filter($notifications,fn($i)=>$i['state']==='Unread'));?>
<div class="ess-header"><button type="button" data-ess-theme aria-label="Switch light and dark mode">◐</button><details class="ess-bell"><summary aria-label="Notifications"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg> <span><?= $unread ?></span></summary><div><strong>Notifications</strong><?php $recent=array_slice(array_values(array_filter($notifications,fn($i)=>$i['state']!=='Archived')),0,5);foreach($recent as $item):?><a href="?page=<?=h($item['page'])?>"><?=h($item['title'])?><small><?=h($item['text'])?></small></a><?php endforeach;if(!$recent):?><p>No new notifications.</p><?php endif;?><a href="?page=inbox">Open inbox</a></div></details><a href="?page=profile"><?=h($user['name'])?></a></div>
